const topic = msg.topic || "";
const parts = topic.split("/");

if (parts.length < 5 || parts[0] !== "nexternel" || parts[4] !== "state") {
    return [null, null];
}

const device = parts[1];
const entityType = parts[2];
const entityId = parts[3];

let value = msg.payload;

if (entityType === "sensor") {
    value = parseFloat(value);
    if (isNaN(value)) return [null, null];
} else if (entityType === "switch") {
    value = value === "ON" ? 1 : 0;
} else {
    return [null, null];
}

msg.device = device;
msg.entityType = entityType;
msg.entityId = entityId;
msg.value = value;

return [msg, msg];

// Set your token here after import:
const token = "REPLACE_WITH_INFLUXDB_TOKEN";
const org = "damnhome";
const bucket = "sensors";

const line = `sensor_reading,device=${msg.device},entity_type=${msg.entityType},entity_id=${msg.entityId} value=${msg.value}`;

msg.url = `http://influxdb:8086/api/v2/write?org=${encodeURIComponent(org)}&bucket=${encodeURIComponent(bucket)}&precision=ms`;
msg.headers = {
    "Authorization": "Token " + token,
    "Content-Type": "text/plain; charset=utf-8"
};
msg.payload = line;

return msg;

if (msg.entityType !== "sensor") return null;
if (msg.entityId !== "living_room_temperature") return null;

const threshold = 28;
const device = msg.device;

if (msg.value > threshold) {
    msg.topic = `nexternel/${device}/switch/fan_relay/command`;
    msg.payload = "ON";
    return msg;
}
if (msg.value < threshold - 2) {
    msg.topic = `nexternel/${device}/switch/fan_relay/command`;
    msg.payload = "OFF";
    return msg;
}
return null;
